globalCSS:
/* ==========================================================
 * Sola Solstice (Dual Mode) — Custom CSS for Lumiverse
 * Automatically harmonizes between Day (Flame) & Night (Ember)
 * ========================================================== */

:root {
  /* Sola Canonical Gradients */
  --sola-solstice: linear-gradient(135deg, #F4A261 0%, #EE6C4D 100%);
  --sola-hearth: linear-gradient(135deg, #E07A5F 0%, #C06C54 100%);
  --sola-dusk: linear-gradient(135deg, #F3B74B 0%, #8592E6 100%);
  --sola-starlight: linear-gradient(135deg, #98B9C7 0%, #8592E6 100%);
}

/* Atmospheric Selection */
::selection {
  background: var(--lumiverse-primary-020);
  color: var(--lumiverse-text);
}

/* Sola Smooth Scrollbar */
::-webkit-scrollbar {
  width: 7px;
  height: 7px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: var(--lumiverse-border);
  border-radius: 9999px;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--lumiverse-border-hover);
}

/* Responsive Prose Styles */
.prose em,
[data-component="MessageContent"] em {
  color: var(--lumiverse-prose-italic) !important;
  font-style: italic;
}

.prose q,
.proseDialogue,
[data-component="MessageContent"] q {
  color: var(--lumiverse-prose-dialogue) !important;
}

.prose blockquote {
  border-left: 3px solid var(--lumiverse-primary) !important;
  background: var(--lumiverse-primary-010);
  padding: 8px 14px;
  border-radius: 0 8px 8px 0;
  color: var(--lumiverse-text-muted);
}

/* Dynamic Primary CTA Buttons */
button[data-variant="primary"],
.btnPrimary {
  background: var(--lumiverse-primary) !important;
  color: var(--lumiverse-primary-contrast, #fff) !important;
  font-weight: 600;
  border: 1px solid var(--lumiverse-border-hover) !important;
  box-shadow: 0 2px 12px var(--lumiverse-primary-020) !important;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

button[data-variant="primary"]:hover,
.btnPrimary:hover {
  background: var(--lumiverse-primary-hover) !important;
  box-shadow: 0 4px 18px var(--lumiverse-primary-050) !important;
  transform: translateY(-1px);
}

/* Focus Rings */
:focus-visible {
  outline: 2px solid var(--lumiverse-primary) !important;
  outline-offset: 2px;
}
